tool.command:

  ln -f -s ${input_stats_pt_path} ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

build_model

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__model_type__dq__:__dq__${properties.model_type}__dq__,__dq__n_cvs__dq__:${properties.n_cvs},__dq__encoder_layers__dq__:${properties.encoder_layers},__dq__decoder_layers__dq__:${properties.decoder_layers},__dq__options__dq__:${properties.options}__cc____cc__'
  #end if

  #if str($input_stats_pt_path) != 'None':
    --input_stats_pt_path ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext}
  #end if


  --output_model_pth_path $outname_output_model_pth_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_stats_pt_path}_`echo $$`.${input_stats_pt_path.ext};


  if test -f $outname_output_model_pth_path; then mv $outname_output_model_pth_path $output_model_pth_path; fi;
